import{_ as a,C as i,o as d,c as h,j as s,a as r,E as o,a2 as n}from"./chunks/framework.CdvW4CUT.js";const w=JSON.parse('{"title":"Zones","description":"","frontmatter":{"title":"Zones"},"headers":[],"relativePath":"en/guide/zones.md","filePath":"en/guide/zones.md"}'),l={name:"en/guide/zones.md"};function g(c,t,m,u,p,f){const e=i("Capture");return d(),h("div",null,[t[0]||(t[0]=s("h1",{id:"zones",tabindex:"-1"},[r("Zones "),s("a",{class:"header-anchor",href:"#zones","aria-label":'Permalink to "Zones"'},"​")],-1)),t[1]||(t[1]=s("p",null,[r("The memory's notes are filed in "),s("strong",null,"zones"),r(", which say what a note is for. Each zone has its own screen: a list you can filter, sort and open, with what you need to create, rename, move or remove a note.")],-1)),o(e,{name:"zone-liste",alt:"The Knowledge zone as a list, filtered on “This year”: one row per note, with its type and project."}),t[2]||(t[2]=n('<h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><h3 id="the-nine-zones" tabindex="-1">The nine zones <a class="header-anchor" href="#the-nine-zones" aria-label="Permalink to &quot;The nine zones&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Zone</th><th>Folder</th><th>What it holds</th></tr></thead><tbody><tr><td><strong>Inbox</strong></td><td><code>00-inbox</code></td><td>Quick captures, waiting to be filed.</td></tr><tr><td><strong>Sessions</strong></td><td><code>10-episodes</code></td><td>Session archives, project by project.</td></tr><tr><td><strong>Knowledge</strong></td><td><code>20-knowledge</code></td><td>Knowledge notes and facts about the code.</td></tr><tr><td><strong>Procedures</strong></td><td><code>30-procedures</code></td><td>How to do a thing, step by step.</td></tr><tr><td><strong>Principles</strong></td><td><code>40-principles</code></td><td>Principles, with their force: red line, heuristic, preference or action rule.</td></tr><tr><td><strong>Goals</strong></td><td><code>50-goals</code></td><td>Goals, with their horizon and deadline.</td></tr><tr><td><strong>People</strong></td><td><code>60-people</code></td><td>People cards.</td></tr><tr><td><strong>Cognition</strong></td><td><code>70-cognition</code></td><td>What bears on how you work and think.</td></tr><tr><td><strong>System</strong></td><td><code>99-meta</code></td><td>Templates and the memory&#39;s service files.</td></tr></tbody></table><h3 id="in-the-sidebar" tabindex="-1">In the sidebar <a class="header-anchor" href="#in-the-sidebar" aria-label="Permalink to &quot;In the sidebar&quot;">​</a></h3><ul><li>Zones are listed under <strong>Memory zones</strong>, each with a colour bar and the number of notes it holds (subfolders included).</li><li>A small chevron unfolds a zone&#39;s subfolders, each with its own count. A zone with no subfolder has no chevron.</li><li>When they exist, <strong>Cognition</strong> and <strong>System</strong> are tucked behind the <strong>Advanced</strong> row, folded by default.</li></ul><h3 id="on-a-zone-screen" tabindex="-1">On a zone screen <a class="header-anchor" href="#on-a-zone-screen" aria-label="Permalink to &quot;On a zone screen&quot;">​</a></h3><ul><li><strong>Header</strong>: the zone&#39;s name (followed by the subfolder if you opened one), its description and the number of notes with the date range (&quot;4 notes, from 04.07.2026 to 30.09.2026&quot;). On the right, a small <strong>density</strong> gauge (the zone&#39;s share of the memory) and the <strong>Folders</strong> and <strong>New</strong> buttons.</li><li><strong>Filters</strong>: pills <strong>All</strong>, <strong>This year</strong>, <strong>This month</strong>, <strong>No project</strong>, and <strong>With links</strong> when the zone has citations. When the zone&#39;s notes are dated, a sort pill <strong>Newest first</strong> / <strong>Oldest first</strong>. On the right: &quot;4 notes · 4 shown&quot;.</li><li><strong>List</strong>: one row per note, with a title on the left and columns that depend on the zone (see below). A dash &quot;—&quot; marks a missing value.</li><li>An empty zone shows &quot;Empty zone&quot; and says what it holds. A filter that rules everything out shows &quot;No note matches this filter&quot;.</li></ul><h3 id="each-zone-s-columns" tabindex="-1">Each zone&#39;s columns <a class="header-anchor" href="#each-zone-s-columns" aria-label="Permalink to &quot;Each zone&#39;s columns&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Zone</th><th>Columns</th><th>Good to know</th></tr></thead><tbody><tr><td><strong>Sessions</strong></td><td>Two sub-groups, <strong>Projects</strong> and <strong>Domains</strong>: a rail on the left, then the chosen project&#39;s or domain&#39;s screen</td><td>The rail gives each project&#39;s number of notes, or each domain&#39;s number of members. The project screen shows its domains, its figures (<strong>Notes</strong>, <strong>Archives</strong>, <strong>Zones</strong>, <strong>Last session</strong>), its history and its archives. The domain screen is described below, in <a href="#the-domain">The domain</a>.</td></tr><tr><td><strong>Knowledge</strong></td><td><strong>Knowledge</strong>, <strong>Type</strong>, <strong>Project</strong>, <strong>Source</strong></td><td>A line &quot;By type: concept 1 · reference 1…&quot; sums up the zone. An &quot;accepted&quot; tag marks accepted notes.</td></tr><tr><td><strong>Principles</strong></td><td>A <strong>Projects</strong> rail, then <strong>Principle</strong>, <strong>Project</strong>, <strong>Strength</strong></td><td>Strength is <strong>Red line</strong>, <strong>Heuristic</strong>, <strong>Preference</strong> or <strong>Action rule</strong>; otherwise &quot;force not declared&quot;.</td></tr><tr><td><strong>Goals</strong></td><td><strong>Goal</strong>, <strong>Project</strong>, <strong>Status</strong>, <strong>Deadline</strong></td><td>Goals are grouped by <strong>Short term</strong>, <strong>Medium term</strong>, <strong>Long term</strong> (or &quot;Horizon not declared&quot;). Status: &quot;open&quot;, &quot;in progress&quot;, &quot;reached&quot;, &quot;abandoned&quot;.</td></tr><tr><td><strong>System</strong></td><td><strong>Sheet</strong>, <strong>Project</strong>, <strong>Citations</strong></td><td>The column reads &quot;cited by 3 notes&quot;.</td></tr><tr><td><strong>Inbox</strong>, <strong>Procedures</strong>, <strong>People</strong>, <strong>Cognition</strong></td><td><strong>Note</strong>, <strong>Project</strong></td><td></td></tr></tbody></table><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><h3 id="open-a-zone" tabindex="-1">Open a zone <a class="header-anchor" href="#open-a-zone" aria-label="Permalink to &quot;Open a zone&quot;">​</a></h3><p>In the sidebar, click a zone&#39;s name, or one of its subfolders after unfolding it. The zone opens in a tab.</p><h3 id="filter-and-sort" tabindex="-1">Filter and sort <a class="header-anchor" href="#filter-and-sort" aria-label="Permalink to &quot;Filter and sort&quot;">​</a></h3><p>In the row of pills, click <strong>This year</strong>, <strong>This month</strong>, <strong>No project</strong> or <strong>With links</strong> to keep only the matching notes; <strong>All</strong> brings them all back. The count on the right says how many notes are shown out of the total. The sort pill flips the order: most recent deposits first, or oldest first.</p><p>In <strong>Sessions</strong>, notes are arranged by the age of their deposit: <strong>Fresh deposit</strong> (30 days or less), <strong>Settled</strong> (up to a year) and <strong>Sealed</strong> (older).</p><h3 id="open-a-note" tabindex="-1">Open a note <a class="header-anchor" href="#open-a-note" aria-label="Permalink to &quot;Open a note&quot;">​</a></h3><p>Click its title: the note opens in a tab. To read and edit it, see <a href="/en/guide/atom.html">Atom and editor</a>.</p><h3 id="create-a-note-or-a-folder" tabindex="-1">Create a note or a folder <a class="header-anchor" href="#create-a-note-or-a-folder" aria-label="Permalink to &quot;Create a note or a folder&quot;">​</a></h3><ol><li>In the zone header, click <strong>New</strong>, then <strong>Note</strong> or <strong>Folder</strong>.</li><li>For a note, fill in <strong>Title</strong>, optionally <strong>File name</strong> (otherwise it is derived from the title), <strong>Scope</strong> (<strong>Work</strong>, <strong>Personal</strong> or <strong>Both</strong>) and, when templates exist, <strong>Template</strong>.</li><li>Click <strong>Create</strong>. The note or folder is created in the zone (or subfolder) you are looking at.</li></ol><h3 id="rename-or-move-a-note" tabindex="-1">Rename or move a note <a class="header-anchor" href="#rename-or-move-a-note" aria-label="Permalink to &quot;Rename or move a note&quot;">​</a></h3>',20)),o(e,{name:"zone-menu-ligne",alt:"A zone row's menu, opened by right-click: open, rename, move, remove."}),t[3]||(t[3]=n('<ol><li>Right-click the note&#39;s row: the menu offers <strong>Open</strong>, <strong>Rename</strong>, <strong>Move</strong> and <strong>Remove</strong>.</li><li><strong>Rename</strong>: change the <strong>Title</strong> and the <strong>File name</strong> (or tick &quot;Keep the current file name&quot;), then <strong>Confirm</strong>. <strong>Move</strong>: choose the <strong>Destination</strong>, then <strong>Move</strong>.</li><li>Kessho first shows &quot;What the operation will do&quot;: the files that will be updated, link by link. Click <strong>Apply</strong> to confirm, or <strong>Cancel</strong>.</li><li>A &quot;Result of the last operation&quot; banner says what was done and offers <strong>Undo</strong>: files and links go back to their previous state.</li></ol><h3 id="remove-a-note" tabindex="-1">Remove a note <a class="header-anchor" href="#remove-a-note" aria-label="Permalink to &quot;Remove a note&quot;">​</a></h3><ol><li>Right-click the note, then <strong>Remove</strong>. You can add a <strong>Reason (optional)</strong>.</li><li>The note goes to the memory&#39;s trash (<code>.trash</code>), with a message saying where it came from. It can be put back.</li><li>If other notes cite it, Kessho lists them under <strong>Cited by</strong> and the button becomes <strong>Remove anyway</strong>.</li></ol><h3 id="manage-folders" tabindex="-1">Manage folders <a class="header-anchor" href="#manage-folders" aria-label="Permalink to &quot;Manage folders&quot;">​</a></h3><p>Click <strong>Folders</strong> in the header: the list of the zone&#39;s subfolders appears, each with <strong>Rename</strong>, <strong>Move</strong> and <strong>Delete</strong>. A folder marked &quot;managed by Kessho&quot; cannot be changed here. Deleting a folder puts it in the trash with all its content; it can be put back.</p><h3 id="see-what-an-agent-has-just-changed" tabindex="-1">See what an agent has just changed <a class="header-anchor" href="#see-what-an-agent-has-just-changed" aria-label="Permalink to &quot;See what an agent has just changed&quot;">​</a></h3>',6)),o(e,{name:"fraicheur",alt:"The freshness indicator, top right: an agent has just written in the Procedures zone, the indicator lights up and says what moved."}),t[4]||(t[4]=n('<p>When an agent writes to the memory while the application is open, the <strong>freshness indicator</strong> lights up. It is the small dot at the top right, next to your profile.</p><ol><li>Click the dot. The panel says how long ago: &quot;Seen a second ago.&quot; With nothing new, it says &quot;No change since opening.&quot;</li><li>Under &quot;Changes since the last reload&quot;, each zone touched is listed with its number of changes. If a note changed without any zone changing size, the panel says so too.</li><li>Click <strong>Reload</strong> to reload the current screen: the lists then show the new state.</li></ol><p>The indicator counts changes, not a size: adding then removing a note makes two.</p><h2 id="the-domain" tabindex="-1">The domain <a class="header-anchor" href="#the-domain" aria-label="Permalink to &quot;The domain&quot;">​</a></h2><p>A <strong>domain</strong> is a cross-cutting scope of work: lighting, art direction, DevOps… It is not a parent folder. A project is not filed <em>inside</em> a domain: it <strong>carries</strong> it, and the same project can carry several domains. The domain brings together the projects that carry it, its own sessions and the knowledge attached to it.</p><p>Domains open from <strong>Sessions</strong>, <strong>Domains</strong> sub-group: the rail lists the memory&#39;s domains, each with its number of members (attached projects and notes), and the screen on the right shows the chosen domain.</p>',6)),o(e,{name:"ecran-de-domaine",alt:"The screen of the “lighting” domain: the two attached projects and their other domains, the thread of sessions from the domain and its projects, the attached knowledge on the right."}),t[5]||(t[5]=n('<h3 id="a-domain-s-screen" tabindex="-1">A domain&#39;s screen <a class="header-anchor" href="#a-domain-s-screen" aria-label="Permalink to &quot;A domain&#39;s screen&quot;">​</a></h3><ul><li><strong>Header</strong>: the domain&#39;s name, the <strong>Domain</strong> badge, its <strong>Phase</strong> (read from its <code>context.md</code>) and three figures: <strong>Projects</strong>, <strong>Sessions</strong>, <strong>Last session</strong>. The <strong>Open the context</strong> link opens its <code>context.md</code>.</li><li><strong>Scope</strong>: the domain&#39;s text, folded to one line by default. <strong>Expand</strong> shows all of it.</li><li><strong>Projects</strong>: one row per attached project, with its <strong>Phase</strong>, its <strong>Last session</strong>, its number of archives and its <strong>Other domains</strong>. An other-domain label opens that domain; &quot;This domain only&quot; says the project carries no other. Clicking a project&#39;s name opens its screen.</li><li><strong>Sessions</strong>: the thread of sessions from the domain <strong>and</strong> its projects, most recent first. A session of the domain itself carries the <strong>Domain</strong> label; a project session carries the project&#39;s identifier. The <strong>Search</strong> field and the <strong>From</strong> / <strong>To</strong> dates filter the thread; the <strong>Own only</strong> box keeps only the domain&#39;s sessions, and the screen says how many project sessions it sets aside.</li><li><strong>Attached knowledge</strong>: on the right, the notes attached to the domain, grouped by kind (principles, goals, procedures, knowledge). Clicking a note opens it.</li></ul><p>Each part is read on its own: if one cannot be read, it says so in its place and the others stay on screen.</p><h3 id="attach-and-detach-a-project" tabindex="-1">Attach and detach a project <a class="header-anchor" href="#attach-and-detach-a-project" aria-label="Permalink to &quot;Attach and detach a project&quot;">​</a></h3><ol><li>To attach a project, click <strong>Attach a project</strong> above the table. A list opens, with a <strong>Search a project</strong> field; projects already attached stay listed, greyed out.</li><li>Choose a project: it joins the table, and its sessions join the thread.</li><li>To detach a project, click <strong>Detach</strong> at the end of its row. Kessho asks for confirmation under the row and recalls that only the project&#39;s <code>context.md</code> is rewritten: its archives stay intact and leave the thread. Confirm with <strong>Detach</strong>.</li></ol><p>After each action, the screen reads the domain again: the table, the thread and the rail&#39;s count show what was written.</p><h3 id="domains-from-a-project-s-screen" tabindex="-1">Domains from a project&#39;s screen <a class="header-anchor" href="#domains-from-a-project-s-screen" aria-label="Permalink to &quot;Domains from a project&#39;s screen&quot;">​</a></h3>',7)),o(e,{name:"domaines-du-projet",alt:"The Lumière Workshop project screen: the Domains row shows its two domains, each with a cross to remove it, and the “Add to a domain” action."}),t[6]||(t[6]=n('<p>In <strong>Sessions</strong>, <strong>Projects</strong> sub-group, a project&#39;s screen carries a <strong>Domains</strong> row under its description. The project&#39;s domains are listed in alphabetical order: none is &quot;main&quot;.</p><ul><li>Clicking a domain&#39;s label opens that domain&#39;s screen.</li><li>A label&#39;s cross removes the project from that domain, after confirmation.</li><li><strong>Add to a domain</strong> lists the memory&#39;s domains, with a <strong>Search a domain</strong> field; those the project already carries are marked &quot;Already attached&quot;.</li><li>A domain named in the project but with no folder in the memory stays on display, without a link.</li></ul><h3 id="what-kessho-writes" tabindex="-1">What Kessho writes <a class="header-anchor" href="#what-kessho-writes" aria-label="Permalink to &quot;What Kessho writes&quot;">​</a></h3><p>Attaching, detaching, adding or removing a domain rewrites <strong>one thing only</strong>: the <code>domain:</code> key of the project&#39;s <code>context.md</code>. No archive is rewritten, no file moves, and the domain itself is not changed. If the write fails, Kessho says so and nothing was changed.</p>',4))])}const y=a(l,[["render",g]]);export{w as __pageData,y as default};
